#include <iostream>
using namespace std;

const long long MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, x, pos;
    cin >> n >> x >> pos;

    int smaller = 0, greater = 0;
    int left = 0, right = n;

    while (left < right) {
        int mid = (left + right) / 2;

        if (mid <= pos) {
            if (mid < pos) ++smaller;
            left = mid + 1;
        } else {
            ++greater;
            right = mid;
        }
    }

    if (smaller > x - 1 || greater > n - x) {
        cout << 0 << '\n';
        return 0;
    }

    long long answer = 1;

    for (int i = 0; i < smaller; ++i)
        answer = answer * (x - 1 - i) % MOD;

    for (int i = 0; i < greater; ++i)
        answer = answer * (n - x - i) % MOD;

    int remaining = n - smaller - greater - 1;
    for (int i = 1; i <= remaining; ++i)
        answer = answer * i % MOD;

    cout << answer << '\n';
    return 0;
}

