#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, x, pos;
    cin >> n >> x >> pos;

    int lessNeeded = 0, greaterNeeded = 0;
    int left = 0, right = n;

    while (left < right) {
        int mid = (left + right) / 2;

        if (mid <= pos) {
            if (mid != pos) ++lessNeeded;
            left = mid + 1;
        } else {
            ++greaterNeeded;
            right = mid;
        }
    }

    if (lessNeeded > x - 1 || greaterNeeded > n - x) {
        cout << 0 << '\n';
        return 0;
    }

    long long answer = 1;

    for (int i = 0; i < lessNeeded; ++i)
        answer = answer * (x - 1 - i) % MOD;

    for (int i = 0; i < greaterNeeded; ++i)
        answer = answer * (n - x - i) % MOD;

    int remaining = n - 1 - lessNeeded - greaterNeeded;
    for (int i = 1; i <= remaining; ++i)
        answer = answer * i % MOD;

    cout << answer << '\n';
    return 0;
}

